# Install __PKG_ID__ into a dedicated dsh profile (no backend/workbench).
# Generated by plugin generate (api-to-plugin S2.4). Paths are local config; no secrets.
param(
    [string]$HarnessDir = '__HARNESS_DIR__',
    [string]$CoreDir = '__CORE_DIR__',
    [string]$RuntimeDir = '__RUNTIME_DIR__',
    [string]$BundleDir = (Join-Path $PSScriptRoot '..'),
    [string]$ProfileName = '__PROFILE_NAME__',
    [switch]$Reset
)

$ErrorActionPreference = 'Stop'

$HarnessDir = (Resolve-Path $HarnessDir).Path
$BundleDir = (Resolve-Path $BundleDir).Path

Push-Location $HarnessDir
try {
    if ($Reset) {
        pnpm dsh --profile $ProfileName --from-default-profile web --dump-config | Out-Null
        if ($LASTEXITCODE -ne 0) { throw "failed to reset profile '$ProfileName'" }
    }
    else {
        $profileDir = Join-Path (Join-Path (Join-Path $env:USERPROFILE '.dsh') 'profiles') $ProfileName
        if (-not (Test-Path $profileDir)) {
            pnpm dsh --profile $ProfileName --from-default-profile web --dump-config | Out-Null
            if ($LASTEXITCODE -ne 0) { throw "failed to create profile '$ProfileName'" }
        }
    }

    # dependencies first (bundle links core/runtime)
    foreach ($pkg in @($CoreDir, $RuntimeDir, $BundleDir)) {
        Push-Location $pkg
        try {
            pnpm install
            if ($LASTEXITCODE -ne 0) { throw "pnpm install failed: $pkg" }
            pnpm run build
            if ($LASTEXITCODE -ne 0) { throw "build failed: $pkg" }
        }
        finally { Pop-Location }
    }

    Push-Location $HarnessDir
    try {
        pnpm dsh plugin --profile $ProfileName add $BundleDir
        if ($LASTEXITCODE -ne 0) { throw "failed to install __PKG_ID__ into '$ProfileName'" }
    }
    finally { Pop-Location }

    Write-Host ""
    Write-Host "__PKG_ID__ profile '$ProfileName' ready (no backend/workbench)."
    Write-Host "  Import:        node scripts\seed-release.mjs"
    Write-Host '  Activate:      node scripts\seed-release.mjs activate "<authorizedBy>"'
    Write-Host "  Data source:   set __ENV_API_URL__ before launch (see .env.example)"
    Write-Host "  Identity:      set DSH_BIZ_USER_ID / DSH_BIZ_TENANT / DSH_BIZ_ROLES"
    Write-Host "  Launch:  pnpm dsh --profile $ProfileName --no-open"
    Write-Host "  Assert:  scripts\dump-config.ps1"
}
finally {
    Pop-Location
}
